INSERT INTO public.courses (id, title, description, subject, learning_level, published, created_at, updated_at)
VALUES
  ('73c09f3f-219b-4e08-9b70-af6c1d34996c', 'Computer Basics', 'Understand computer hardware, software, files and digital safety.', 'ICT', 'Beginner', true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00'),
  ('d3ad5154-fe7b-4c89-a788-49409bf4f051', 'CSS Web Design', 'Learn to style web pages with layouts, colours and responsive design.', 'ICT', 'Beginner', true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00'),
  ('e0b811f0-4200-4393-b6ff-f4f37dc0c996', 'HTML Fundamentals', 'Learn the structure of web pages and build your first website.', 'ICT', 'Beginner', true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00'),
  ('684ed4c4-9709-4768-8fa0-5d522f250aa2', 'JavaScript Essentials', 'Explore programming fundamentals and interactive web development.', 'ICT', 'Beginner', true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00'),
  ('0f6552c1-5657-4d7e-82e8-044f67381a8e', 'Mathematics Revision', 'Practise mathematics concepts and strengthen problem-solving skills.', 'Mathematics', 'Secondary', true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00')
INSERT INTO public.learning_resources (id, title, description, subject, resource_type, content, file_url, published, created_at, updated_at)
VALUES
  ('ca02de0e-1731-4078-b39c-ce7924d3e5f8', 'Introduction to HTML', 'A beginner-friendly introduction to HTML elements.', 'ICT', 'article', 'HTML is the standard markup language for structuring web pages. Start with headings, paragraphs, links and images.', NULL, true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00'),
  ('7faa4671-3e9f-4f96-892c-6dbe180d3ca8', 'Safe Internet Practices', 'Learn how to protect your accounts and personal information.', 'ICT', 'article', 'Use strong unique passwords, enable two-factor authentication, avoid suspicious links and never share your passwords.', NULL, true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00'),
  ('92bb8c2b-8cd2-4565-9745-d0418966d3d7', 'Study Planning Guide', 'Simple techniques for organising holiday revision.', 'Study Skills', 'guide', 'Set realistic study goals, divide topics into manageable sections, take breaks and review what you have learned.', NULL, true, '2026-10-29 10:24:27.468917+00', '2026-10-29 10:24:27.468917+00')
INSERT INTO public.course_lessons (id, course_id, title, summary, content, lesson_order, published, created_at, updated_at, learning_objectives, explanation, worked_example, practice_task, expected_result, learner_exercise, key_takeaways)
VALUES
  ('6075a2c3-76b0-43a9-b71e-8c4e1c5dc64b', '0f6552c1-5657-4d7e-82e8-044f67381a8e', 'Fractions and equivalent fractions', 'Learn the key ideas and practise with the examples in this lesson.', 'A fraction represents part of a whole. The numerator is the top number and the denominator is the bottom number. Equivalent fractions have the same value: 1/2 = 2/4 = 3/6. Multiply or divide both parts by the same non-zero number.', 1, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Identify a fraction and its parts', 'Recognise equivalent fractions', 'Create equivalent fractions using multiplication or division']::text[], 'A fraction represents equal parts of a whole. The numerator is the number of parts being considered; the denominator is the total number of equal parts. Equivalent fractions look different but represent the same value. To make an equivalent fraction, multiply or divide both numerator and denominator by the same non-zero number.', 'Example: 1/2 = 2/4. Multiply the numerator and denominator of 1/2 by 2: (1 × 2)/(2 × 2) = 2/4. Both fractions represent one half.', 'Draw a rectangle, divide it into 4 equal parts and shade 2. Then draw another rectangle divided into 8 equal parts and shade 4. Compare the shaded portions.', 'Both drawings should show the same shaded amount: 2/4 and 4/8 are equivalent to 1/2.', 'Write two fractions equivalent to 3/4. Explain which number you multiplied the numerator and denominator by.', ARRAY['The numerator is above the fraction bar', 'The denominator is below the fraction bar', 'Multiply or divide both parts by the same non-zero number']::text[]),
  ('dd4f966f-40b3-458b-8d5f-4941b7718b69', '0f6552c1-5657-4d7e-82e8-044f67381a8e', 'Percentages', 'Learn the key ideas and practise with the examples in this lesson.', 'Percent means per hundred. To change a percentage into a decimal, divide by 100: 25% = 0.25. To find 20% of 150, calculate 0.20 times 150 = 30.', 2, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain what percent means', 'Convert percentages to decimals', 'Calculate a percentage of a quantity']::text[], 'Percent means per hundred. A percentage can be written as a fraction with denominator 100 or as a decimal. To convert a percentage to a decimal, divide by 100. To find a percentage of an amount, convert the percentage to a decimal and multiply.', 'Find 20% of 150. Convert 20% to 0.20, then calculate 0.20 × 150 = 30. Therefore, 20% of 150 is 30.', 'Use 100 small squares or draw a 10 by 10 grid. Shade 25 squares to represent 25%. Then calculate 25% of 200.', '25% of 200 is 50. One quarter of 200 is 50.', 'Calculate 15% of 300 and 40% of 80. Show the conversion to decimals and each multiplication.', ARRAY['Percent means per hundred', 'Divide by 100 to convert a percentage to a decimal', 'Multiply the decimal by the amount']::text[]),
  ('25d63a81-4440-497b-9d33-e38b6db514d7', '0f6552c1-5657-4d7e-82e8-044f67381a8e', 'Introduction to algebra', 'Learn the key ideas and practise with the examples in this lesson.', 'Algebra uses letters to represent numbers. In 3x + 2, x is a variable, 3 is its coefficient and 2 is a constant. To solve x + 5 = 12, subtract 5 from both sides: x = 7.', 3, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain why letters are used in algebra', 'Identify variables, coefficients and constants', 'Solve a simple one-step equation']::text[], 'Algebra uses letters to represent numbers that may be unknown or may change. A variable is the letter, a coefficient is the number multiplying the variable, and a constant is a number without a variable. An equation says two expressions are equal. Keep an equation balanced by performing the same operation on both sides.', 'Solve x + 5 = 12. Subtract 5 from both sides: x + 5 − 5 = 12 − 5. Therefore x = 7. Check: 7 + 5 = 12.', 'Create a balance-scale drawing. Put x + 3 on one side and 10 on the other. Remove 3 from both sides and identify the value of x.', 'The equation becomes x = 7. Both sides remain equal because the same amount was removed.', 'Solve x + 8 = 19 and 3x = 21. Show each step and check your answers by substitution.', ARRAY['A variable represents a number', 'A coefficient multiplies a variable', 'Perform the same operation on both sides of an equation']::text[]),
  ('8ea8ca15-a623-4c96-b95f-bb993490f244', '684ed4c4-9709-4768-8fa0-5d522f250aa2', 'Your first JavaScript', 'Learn the key ideas and practise with the examples in this lesson.', 'JavaScript adds behaviour to web pages. Try: const greeting = "Hello, learner"; console.log(greeting); The const keyword creates a variable whose binding should not be reassigned. Open the browser developer console to view the message.', 1, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain what JavaScript does on a webpage', 'Recognise a JavaScript statement', 'Run a simple console message']::text[], 'JavaScript is a programming language that can make web pages respond to user actions and update content. A statement is an instruction. The console is a browser tool where developers can view messages and errors while testing code.', 'Try this JavaScript: const greeting = "Hello, learner"; console.log(greeting); The first statement stores text in a constant. The second prints that text in the developer console.', 'Open your browser developer tools, select Console, and run the example. Change the message to a greeting of your own and run it again.', 'The console displays the exact greeting stored in the greeting variable.', 'Create a constant named school and store the name of a school in it. Use console.log() to display the value.', ARRAY['JavaScript adds behaviour to webpages', 'Statements are instructions', 'console.log() displays information in the developer console']::text[]),
  ('5980839c-a393-4880-bc6f-9ed4ff54f247', '684ed4c4-9709-4768-8fa0-5d522f250aa2', 'Variables and data types', 'Learn the key ideas and practise with the examples in this lesson.', 'Variables store values. Use const when you will not reassign a variable and let when its value needs to change. Common data types include strings, numbers, booleans, arrays and objects.', 2, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain what a variable stores', 'Choose between const and let', 'Recognise common JavaScript data types']::text[], 'A variable is a named place for a value. Use const when you do not plan to reassign the variable. Use let when the value needs to change. Common data types include strings for text, numbers, booleans for true or false, arrays for ordered collections and objects for grouped properties.', 'const learnerName = "Amina"; let score = 10; score = 15; The name is kept in a const variable, while score is declared with let because it is reassigned.', 'Write one string, one number and one boolean variable. Use console.log() to display each value and typeof to inspect its type.', 'The console should display the values and their types, such as string, number and boolean.', 'Create variables for a subject name, number of lessons and whether a learner is registered. Choose suitable data types and explain your choices.', ARRAY['Variables store values', 'const prevents reassignment of the binding', 'let allows reassignment', 'JavaScript values have different data types']::text[]),
  ('acf03cfb-4283-44bd-94f1-8693444395fa', '684ed4c4-9709-4768-8fa0-5d522f250aa2', 'Conditions and functions', 'Learn the key ideas and practise with the examples in this lesson.', 'An if statement runs code when a condition is true. Example: if (score >= 50) { console.log("Pass"); } A function groups reusable instructions: function add(a, b) { return a + b; } Call it with add(2, 3).', 3, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain how a condition controls program flow', 'Write a simple if statement', 'Describe why functions are useful']::text[], 'A condition is an expression that evaluates to true or false. An if statement runs a block only when its condition is true. A function is a reusable group of instructions. Functions can receive inputs called parameters and can return a result.', 'Example: if (score >= 50) { console.log("Pass"); } This displays Pass when score is at least 50. A reusable function is: function add(a, b) { return a + b; } Calling add(2, 3) returns 5.', 'Change the score in the condition to 40 and then 65. Run the code and observe when the message appears. Next, call add() with two different pairs of numbers.', 'The pass message appears only when the score is 50 or higher. The add function returns the sum of its two inputs.', 'Write a function that accepts a learner mark and returns whether it is a pass when the mark is at least 50. Test it with 35 and 70.', ARRAY['if statements make decisions', 'Conditions evaluate to true or false', 'Functions organise reusable instructions']::text[]),
  ('e16e7d79-a11b-4811-a01f-ac46fda7017c', '73c09f3f-219b-4e08-9b70-af6c1d34996c', 'Computer hardware', 'Learn the key ideas and practise with the examples in this lesson.', 'Hardware means the physical parts of a computer. Examples include the monitor, keyboard, mouse, processor, memory and storage drive. Input devices send information to a computer; output devices present results.', 1, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Define computer hardware', 'Identify common input and output devices', 'Distinguish processing, memory and storage']::text[], 'Hardware means the physical parts of a computer that can be seen and touched. Input devices send data to a computer, output devices present information, the processor carries out instructions, memory holds data currently in use and storage keeps data for later use.', 'When typing a document, the keyboard is an input device. The CPU processes instructions, RAM holds working data, and the monitor is an output device. A storage drive keeps the document after it is saved.', 'Observe a computer or draw one. Label its monitor, keyboard, mouse, processor and storage device. Classify each as input, output, processing or storage.', 'The keyboard and mouse are input devices; the monitor is output; the CPU processes instructions; storage keeps files.', 'A learner prints a document. Identify the input device used to create it, the component that processes instructions and the output device that produces the paper copy.', ARRAY['Hardware is physical computer equipment', 'Input sends data in; output presents results', 'The CPU processes instructions', 'Memory and storage have different roles']::text[]),
  ('c59e0529-8e51-4624-8b8e-abf4e185783b', '73c09f3f-219b-4e08-9b70-af6c1d34996c', 'Software and operating systems', 'Learn the key ideas and practise with the examples in this lesson.', 'Software is a set of instructions that tells hardware what to do. System software includes the operating system, which manages files, devices and applications. Application software helps users perform tasks.', 2, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Define software', 'Distinguish system software from application software', 'Explain the role of an operating system']::text[], 'Software is a collection of programs and instructions. System software manages the computer and provides a platform for other programs. An operating system manages hardware, files, memory and applications. Application software helps people perform specific tasks such as writing documents or browsing the web.', 'On a computer, Windows manages devices and allows programs to run. A word processor is application software used to create documents. The operating system helps the word processor access files and the printer.', 'Look at the programs available on a computer or phone. List the operating system and three applications. Describe one task each application helps you perform.', 'You should identify one operating system and distinguish it from programs used for specific tasks.', 'Classify a web browser, operating system, spreadsheet program and device driver as system or application software. Give a reason for each classification.', ARRAY['Software is made of programs and instructions', 'System software manages the computer', 'Application software helps users perform tasks']::text[]),
  ('c8e271c6-d676-414c-9a2b-d86a1af5ae94', '73c09f3f-219b-4e08-9b70-af6c1d34996c', 'Files, folders and digital safety', 'Learn the key ideas and practise with the examples in this lesson.', 'Files store information; folders organise files. Use clear names and keep related work together. Keep software updated, use strong unique passwords, and avoid opening unexpected attachments or sharing private information with strangers.', 3, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain the difference between files and folders', 'Organise files using clear names', 'Recognise safe digital habits']::text[], 'A file stores information such as a document, picture or presentation. A folder groups files so they are easier to find. Good digital organisation uses meaningful names and sensible folders. Digital safety includes protecting passwords, updating software, checking unexpected messages and keeping personal information private.', 'Create a folder called School Work, then a folder inside it called ICT. Save a document as HTML_Practice_01 rather than New Document. The name makes its purpose easier to recognise.', 'Plan a folder structure for school work with folders for ICT, Mathematics and English. Give each folder two example file names.', 'Your structure should group related files and use names that make the contents clear.', 'A message from an unknown sender asks you to open an attachment and enter your password. Explain two safe steps you should take before doing anything.', ARRAY['Files contain information; folders organise files', 'Clear names make work easier to find', 'Use unique passwords and keep software updated', 'Be cautious with unexpected links and attachments']::text[]),
  ('4f4f7795-8fcb-41a6-9a19-2ee0fbcec98e', 'd3ad5154-fe7b-4c89-a788-49409bf4f051', 'What CSS does', 'Learn the key ideas and practise with the examples in this lesson.', 'CSS controls the appearance and layout of HTML pages. A rule has a selector and declarations. Example: h1 { color: navy; font-size: 2rem; } CSS can be written in a style element or an external CSS file.', 1, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain the purpose of CSS', 'Identify a CSS rule, selector and declaration', 'Connect CSS to an HTML page']::text[], 'CSS means Cascading Style Sheets. It controls how HTML content looks, including colours, fonts, spacing and layout. A CSS rule contains a selector, which chooses elements, and declarations, which set properties and values.', 'h1 { color: navy; font-size: 2rem; } The h1 selector targets level-one headings. The color declaration changes the text colour, while font-size changes its size.', 'Create a simple HTML page with a heading. Add a style element in the head and use the example rule to change the heading colour and size.', 'The heading should appear in navy and be larger than normal paragraph text.', 'Write a CSS rule that makes all paragraphs dark green and gives them a font size of 18 pixels. Identify the selector and both declarations.', ARRAY['CSS controls presentation', 'A selector chooses elements', 'Declarations contain properties and values', 'CSS can be embedded or stored in an external stylesheet']::text[]),
  ('d7846075-98b7-40e3-a2f5-098eac0076d2', 'd3ad5154-fe7b-4c89-a788-49409bf4f051', 'Selectors, colours and spacing', 'Learn the key ideas and practise with the examples in this lesson.', 'Element selectors target tags, class selectors begin with a dot, and ID selectors begin with #. Example: .notice { background: lavender; padding: 16px; margin: 12px 0; } Padding is space inside an element; margin is space outside it.', 2, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Recognise element, class and ID selectors', 'Apply colour styles', 'Explain padding and margin']::text[], 'An element selector targets HTML tags such as p. A class selector starts with a dot and can be reused on many elements. An ID selector starts with # and should identify one unique element on a page. Padding is space inside an element; margin is space outside it.', '.notice { background: lavender; padding: 16px; margin: 12px 0; } This rule targets every element with class notice, adds space inside it and separates it from nearby elements.', 'Create two paragraphs with the same class notice. Apply the example rule, then change the background colour and padding.', 'Both paragraphs should receive the same background and spacing because they share the class.', 'Write one class selector for a warning message and one ID selector for a page header. Give each a different text colour.', ARRAY['Element selectors target tags', 'Class selectors are reusable and start with a dot', 'ID selectors start with #', 'Padding is inside; margin is outside']::text[]),
  ('9d7decf0-9457-4ed9-8c5f-25187cb674e1', 'd3ad5154-fe7b-4c89-a788-49409bf4f051', 'Responsive layouts', 'Learn the key ideas and practise with the examples in this lesson.', 'Responsive design helps a page work on different screen sizes. Flexible widths, CSS Grid and Flexbox help organise content. A media query can apply styles at selected viewport widths. Test your page on narrow and wide screens.', 3, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain responsive web design', 'Identify flexible layout techniques', 'Describe how media queries work']::text[], 'Responsive design helps a website remain usable on phones, tablets and computers. Flexible widths avoid fixed layouts that overflow. Flexbox arranges items along one dimension, while CSS Grid helps create rows and columns. Media queries apply CSS when conditions such as viewport width are met.', '@media (max-width: 600px) { .container { grid-template-columns: 1fr; } } This rule changes a grid to one column when the viewport is 600 pixels wide or narrower.', 'Create a two-column card layout using CSS Grid. Add the media query from the example so the cards stack on a narrow screen. Resize the browser window.', 'The cards should appear in two columns on a wider screen and one column on a narrow screen.', 'Design a responsive layout for three subject cards. Explain how it should behave on a desktop and on a phone.', ARRAY['Responsive design adapts to screen sizes', 'Flexible layouts reduce overflow', 'Flexbox and Grid arrange content', 'Media queries apply styles under selected conditions']::text[]),
  ('8b7f6919-8b8f-4717-a321-bb15c12104fd', 'e0b811f0-4200-4393-b6ff-f4f37dc0c996', 'What HTML does', 'Learn the key ideas and practise with the examples in this lesson.', 'HTML gives a web page its structure. It uses elements written with tags. Example: <h1>My first page</h1>. Paragraphs use <p>Text here</p>. Links use <a href="https://example.com">Visit</a>.', 1, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Explain the purpose of HTML', 'Recognise elements and tags', 'Identify common HTML page elements']::text[], 'HTML means HyperText Markup Language. It describes the structure and meaning of webpage content. An element is commonly made from an opening tag, content and a closing tag. Tags such as h1, p and a identify headings, paragraphs and links.', '<h1>My first page</h1>\n<p>Welcome to my webpage.</p>\n<a href="https://example.com">Visit example</a> The heading introduces the page, the paragraph provides text and the anchor creates a link.', 'Write a small HTML fragment containing one heading, one paragraph and one link. Save it in an HTML file and open it in a browser.', 'The browser should show a heading, a paragraph and a clickable link.', 'Create a short introduction about a hobby using one h1 heading and two paragraphs. Add a link to a related website.', ARRAY['HTML provides webpage structure', 'Elements use tags to describe content', 'Headings, paragraphs and links have different purposes']::text[]),
  ('c744c47c-263a-4170-8945-f202b33fb98d', 'e0b811f0-4200-4393-b6ff-f4f37dc0c996', 'Build a basic HTML document', 'Learn the key ideas and practise with the examples in this lesson.', 'A page starts with <!DOCTYPE html>, then html, head and body elements. The head contains page information such as the title. The body contains visible content. Create index.html with a heading and paragraph, then open it in a browser.', 2, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Identify the main parts of an HTML document', 'Explain the purpose of head and body', 'Create and open a basic webpage']::text[], 'A standard HTML document begins with a doctype declaration. The html element contains the whole page. The head contains information about the page, such as its title and character encoding. The body contains the content visitors see.', '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <title>My Page</title>\n</head>\n<body>\n  <h1>Hello</h1>\n  <p>My first webpage.</p>\n</body>\n</html>', 'Create a file named index.html. Type the example structure, save it and open it in a browser. Change the title and visible heading.', 'The browser tab should show My Page (or your changed title) and the page should display the heading and paragraph.', 'Create a webpage about your school with a suitable title, one main heading and two paragraphs. Include the language attribute and character encoding.', ARRAY['The doctype declares an HTML document', 'The head stores page information', 'The body contains visible webpage content', 'Save the file with an .html extension']::text[]),
  ('6e5f9fe5-9a19-41fe-be32-5855d59ffb71', 'e0b811f0-4200-4393-b6ff-f4f37dc0c996', 'Text, links and images', 'Learn the key ideas and practise with the examples in this lesson.', 'Use h1 to h6 for headings and p for paragraphs. Use a with href to create a link. Use img with src and alt attributes for an image. Practise by creating a page with a heading, two paragraphs, one link and one image.', 3, true, '2026-11-05 09:49:03.152862+00', '2026-11-05 09:49:03.152862+00', ARRAY['Use headings and paragraphs to organise text', 'Create hyperlinks with the anchor element', 'Add images with meaningful alternative text']::text[], 'HTML provides elements for common page content. Headings from h1 to h6 organise sections by importance. Paragraphs use p. Links use the anchor element with an href destination. Images use img with a source and descriptive alt text so people using assistive technology can understand the image.', '<h1>My Hobbies</h1>\n<p>I enjoy reading and football.</p>\n<a href="https://example.com">Explore a topic</a>\n<img src="football.jpg" alt="A football on a field">', 'Build a page with one heading, two paragraphs, one link and one image. If you do not have an image file, use a suitable image you already have permission to use.', 'The page should display structured text, a working link and an image with alternative text.', 'Create a mini profile page with a heading, two paragraphs, a link to a learning resource and an image. Explain why the alt attribute matters.', ARRAY['Use headings in a meaningful order', 'Use paragraphs for blocks of text', 'The href attribute sets a link destination', 'The alt attribute describes an image']::text[])
